ThemeSync implementation:

```tsx
function ThemeSync() {
  const hasClient = useContext(QueryClientContext) !== undefined
  if (!hasClient) return null
  return <ThemeSyncInner />
}

function ThemeSyncInner() {
  const user = useAuth(s => s.user)
  const theme = useTheme(s => s.theme)
  const setTheme = useTheme(s => s.setTheme)
  const { data: settings } = useSettings({ enabled: !!user })
  const { mutate: updateSettings } = useUpdateSettings()

  // 서버 → 클라이언트: 로그인 사용자의 저장된 테마를 반영
  useEffect(() => {
    if (settings?.theme && settings.theme !== useTheme.getState().theme) {
      setTheme(settings.theme)
    }
  }, [settings?.theme])

  // 클라이언트 → 서버: 사용자가 변경한 테마를 DB에 저장
  const lastSynced = useRef<string | null>(null)
  useEffect(() => {
    if (!user) return
    // 서버에서 방금 받은 값을 다시 PUT하지 않도록 마지막 동기화 값을 기록
    if (lastSynced.current === theme) return
    if (settings && settings.theme === theme) { lastSynced.current = theme; return }
    lastSynced.current = theme
    updateSettings(theme)
  }, [theme, user, settings])

  return null
}
```

